import copy

def merge_configs(layers):
    out = {}
    for layer in layers:
        _merge(out, layer)
    return out

def _merge(dst, src):
    for key, value in src.items():
        if value is None:
            dst.pop(key, None)
        elif isinstance(value, dict) and isinstance(dst.get(key), dict):
            _merge(dst[key], value)
        else:
            dst[key] = copy.deepcopy(value)

def parse_records(lines):
    records, errors = [], []
    for number, line in enumerate(lines, start=1):
        parts = [p.strip() for p in line.split(',')]
        if len(parts) != 3:
            errors.append({'line': number, 'reason': 'wrong_field_count'})
            continue
        raw_id, name, raw_score = parts
        try:
            record_id = int(raw_id)
        except ValueError:
            errors.append({'line': number, 'reason': 'bad_id'})
            continue
        if record_id <= 0:
            errors.append({'line': number, 'reason': 'bad_id'})
            continue
        try:
            score = float(raw_score)
        except ValueError:
            errors.append({'line': number, 'reason': 'bad_score'})
            continue
        if not 0.0 <= score <= 100.0:
            errors.append({'line': number, 'reason': 'bad_score'})
            continue
        records.append({'id': record_id, 'name': name, 'score': score})
    return {'records': records, 'errors': errors}

import heapq

def resolve_import_order(modules):
    nodes = set(modules)
    for deps in modules.values():
        nodes |= set(deps)
    indegree = {n: 0 for n in nodes}
    dependents = {n: [] for n in nodes}
    for module, deps in modules.items():
        for dep in set(deps):
            dependents[dep].append(module)
            indegree[module] += 1
    ready = [n for n in nodes if indegree[n] == 0]
    heapq.heapify(ready)
    order = []
    while ready:
        node = heapq.heappop(ready)
        order.append(node)
        for nxt in dependents[node]:
            indegree[nxt] -= 1
            if indegree[nxt] == 0:
                heapq.heappush(ready, nxt)
    return order if len(order) == len(nodes) else []

def diff_records(old, new):
