code.prompt:
A PII redactor produces overlapping spans from several detectors. Before writing the masked text you must flatten them into a non-overlapping cover.

Implement `merge_redaction_spans(spans)`. Each span is `[start, end, priority, label]` with `end` **exclusive**. For every character position covered by at least one span, the winning span is:
1. the one with the highest `priority`;
2. on a tie, the one with the smallest `start`;
3. on a further tie, the one appearing earliest in the input list.

Return the resulting cover as `[start, end, label]` triples sorted by `start`, with **adjacent** runs carrying the same label merged into one triple. Positions covered by no span are omitted.

code.reference_solution:
def merge_redaction_spans(spans):
    if not spans:
        return []
    boundaries = sorted({p for s in spans for p in (s[0], s[1])})
    out = []
    for lo, hi in zip(boundaries, boundaries[1:]):
        best = None
        for index, (start, end, priority, label) in enumerate(spans):
            if start <= lo and hi <= end:
                key = (-priority, start, index)
                if best is None or key < best[0]:
                    best = (key, label)
        if best is None:
            continue
        label = best[1]
        if out and out[-1][2] == label and out[-1][1] == lo:
            out[-1][1] = hi
        else:
            out.append([lo, hi, label])
    return out

import re

def parse_requirements(lines):
    result = {}
    for raw in lines:
        line = raw.split(' #')[0].strip()
        if not line or line.startswith('#') or line.startswith('-'):
            continue
        match = re.match(r'^([A-Za-z0-9._-]+)(\[[^\]]*\])?\s*(.*)$', line)
        if not match:
            continue
        name = re.sub(r'[-_.]+', '-', match.group(1)).lower()
        result[name] = re.sub(r'\s+', '', match.group(3))
    return result

def resolve_env(defaults, dotenv, os_env, cli):
    resolved = dict(defaults)
    for layer in (dotenv, os_env, cli):
        for key, raw in layer.items():
            if key not in defaults:
                continue
            resolved[key] = _coerce(raw, defaults[key], resolved[key])
    return resolved

TRUE_TOKENS = {'1', 'true', 'yes', 'on'}
FALSE_TOKENS = {'0', 'false', 'no', 'off', ''}

def _coerce(raw, default, current):
    text = str(raw).strip()
    if isinstance(default, bool):
        lowered = text.lower()
        if lowered in TRUE_TOKENS:
            return True
        if lowered in FALSE_TOKENS:
            return False
        return current
    if isinstance(default, int):
        try:
            return int(text)
        except ValueError:
            return current
    if isinstance(default, float):
        try:
            return float(text)
        except ValueError:
            return current
    return text

def tests_to_run(changed, dependents):
    seen = set()
    stack = list(changed)
    while stack:
        module = stack.pop()
        if module in seen:
            continue
        seen.add(module)
        stack.extend(dependents.get(module, []))
    return sorted(seen)

def three_way_merge(base, ours, theirs):
    if ours == theirs:
        return list(ours)
    if ours == base:
        return list(theirs)
    if theirs == base:
        return list(ours)
    shortest = min(len(base), len(ours), len(theirs))
    prefix_len = 0
    while prefix_len < shortest and base[prefix_len] == ours[prefix_len] == theirs[prefix_len]:
        prefix_len += 1
    suffix_len = 0
    while (suffix_len < shortest - prefix_len
           and base[-1 - suffix_len] == ours[-1 - suffix_len] == theirs[-1 - suffix_len]):
        suffix_len += 1
    def middle(seq):
        return seq[prefix_len:len(seq) - suffix_len]
    base_mid, ours_mid, theirs_mid = middle(base), middle(ours), middle(theirs)
    if ours_mid == base_mid:
        merged = theirs_mid
    elif theirs_mid == base_mid:
        merged = ours_mid
    else:
        merged = (['<<<<<<< ours'] + ours_mid + ['=======']
                  + theirs_mid + ['>>>>>>> theirs'])
    suffix = base[len(base) - suffix_len:] if suffix_len else []
    return list(base[:prefix_len]) + merged + list(suffix)
